import{_ as s,o as t,c as a,ah as n}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Bien démarrer","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/prise-en-main.md","filePath":"src/guide/prise-en-main.md"}'),r={name:"guide/prise-en-main.md"};function i(o,e,l,u,d,c){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="bien-demarrer" tabindex="-1">Bien démarrer <a class="header-anchor" href="#bien-demarrer" aria-label="Permalink to &quot;Bien démarrer&quot;">​</a></h1><p>Cette page est commune à tous les rôles : connexion, profil, sécurité, notifications et langue fonctionnent de la même façon, que vous soyez administrateur, enseignant, parent ou élève. Les guides propres à chaque rôle ne répètent pas ces informations.</p><h2 id="se-connecter" tabindex="-1">Se connecter <a class="header-anchor" href="#se-connecter" aria-label="Permalink to &quot;Se connecter&quot;">​</a></h2><p>Ouvrez l&#39;adresse de votre établissement dans un navigateur et saisissez votre e-mail et votre mot de passe sur l&#39;écran de connexion. Si votre établissement l&#39;a activé, vous pouvez aussi vous connecter avec un compte Google ou Apple.</p><p>Si l&#39;authentification à deux facteurs est activée sur votre compte, un code supplémentaire vous sera demandé après le mot de passe (voir « Authentification à deux facteurs » plus bas).</p><p>Une fois connecté, vous arrivez sur votre tableau de bord (voir ci-dessous). Les parents et les élèves arrivent directement sur leur propre espace : <strong>Mes enfants</strong> pour un parent, l&#39;espace élève pour un élève.</p><h2 id="se-reperer-dans-l-application" tabindex="-1">Se repérer dans l&#39;application <a class="header-anchor" href="#se-reperer-dans-l-application" aria-label="Permalink to &quot;Se repérer dans l&#39;application&quot;">​</a></h2><p>Toutes les pages partagent la même organisation, pensée comme une chemise qui tient ses feuilles :</p><ul><li><p><strong>Les espaces</strong>, dans la colonne bleu foncé à gauche : Accueil, Élèves et admissions, Enseignement, Vie scolaire, Services aux élèves, Finances, Personnel, et en bas Paramétrage scolaire et Administration. La colonne les nomme en abrégé (<strong>Élèves</strong>, <strong>Cours</strong>, <strong>Services</strong>, <strong>Paramétrage</strong>, <strong>Admin</strong>) ; leur nom complet s&#39;affiche en haut de la page. Vous ne voyez que les espaces auxquels votre rôle donne accès.</p></li><li><p><strong>Les onglets</strong>, en haut de la page : les pages de l&#39;espace ouvert. Par exemple, l&#39;espace <strong>Vie scolaire</strong> propose Présences, Justifications d&#39;absence, Incidents disciplinaires, Conseils de discipline et Présences périscolaires. Dans ce guide, un chemin comme <strong>Vie scolaire → Présences</strong> désigne l&#39;espace puis l&#39;onglet.</p></li><li><p><strong>Le bandeau</strong> sous les onglets : le titre de la page, sa description et ses actions principales (par exemple <strong>Nouvel utilisateur</strong>). Sur une page de détail, les pages parentes s&#39;affichent au-dessus du titre et permettent d&#39;y revenir.</p></li><li><p><strong>L&#39;année et la période consultées</strong>, en haut à droite sur ordinateur et tablette : l&#39;année scolaire, la période (par exemple <strong>Trimestre 1</strong>) et, si l&#39;établissement a plusieurs sites, le site. Au départ, ERA se place sur l&#39;année en cours et la période du jour, calculées à partir des dates saisies.</p><p>Cliquez dessus pour consulter une autre année ou une autre période. Ce choix vaut pour toutes les pages : les listes, les filtres et les tableaux de bord s&#39;y adaptent, et il vous suit d&#39;un écran à l&#39;autre. À l&#39;inverse, choisir une année passée sur un écran (par exemple le filtre de la facturation) met à jour ce choix partout.</p><div class="warning custom-block"><p class="custom-block-title">Consulter n&#39;est pas saisir</p><p>Ce sélecteur ne change <strong>jamais</strong> l&#39;année dans laquelle l&#39;application écrit. Une inscription, une candidature approuvée ou un transfert atterrissent toujours dans l&#39;année marquée comme courante, même si vous consultez une année passée. Tant que vous n&#39;êtes pas sur l&#39;année et la période du jour, un bandeau orange vous le rappelle en haut de l&#39;écran, avec un lien <strong>Revenir à aujourd&#39;hui</strong>.</p></div></li><li><p><strong>Votre avatar</strong>, en bas de la colonne des espaces, ouvre vos <strong>Paramètres</strong> et la déconnexion.</p></li></ul><p>Sur téléphone, les espaces passent dans une barre en bas de l&#39;écran. S&#39;il y en a plus de cinq, le bouton <strong>Plus</strong> les liste tous avec leurs pages. Les onglets de l&#39;espace s&#39;affichent sous la barre du haut, et votre avatar est en haut à droite.</p><h2 id="votre-tableau-de-bord" tabindex="-1">Votre tableau de bord <a class="header-anchor" href="#votre-tableau-de-bord" aria-label="Permalink to &quot;Votre tableau de bord&quot;">​</a></h2><p>Le tableau de bord rassemble ce qui vous concerne aujourd&#39;hui.</p><p>Dans le bandeau bleu, la <strong>réglette du trimestre</strong> montre la période en cours, la semaine où vous en êtes et les dates de début et de fin. Juste en dessous, à cheval sur le bandeau, les <strong>chiffres du jour</strong> donnent l&#39;essentiel en un coup d&#39;œil (élèves inscrits, taux d&#39;absentéisme, montant encaissé, échéances dépassées). Ils n&#39;apparaissent que si votre rôle y donne accès.</p><p>Le reste de la page se lit en deux colonnes :</p><ul><li><strong>À traiter</strong> : ce qui attend une action de votre part, avec le nombre d&#39;éléments concernés. Cliquez sur une ligne pour ouvrir l&#39;écran où les traiter. Une ligne disparaît dès qu&#39;il n&#39;y a plus rien à faire ; quand tout est à jour, le bloc affiche « Rien ne vous attend pour le moment ».</li><li><strong>Les blocs du jour</strong>, à droite : ce qui se passe aujourd&#39;hui dans l&#39;établissement pour votre rôle. Sur un grand écran, cette colonne reste visible pendant que vous faites défiler le reste.</li></ul><p>Sur téléphone, un enseignant voit d&#39;abord une carte <strong>Maintenant</strong>, avec le cours en cours — ou le suivant s&#39;il n&#39;y en a pas — et le bouton <strong>Faire l&#39;appel</strong>.</p><p>Si vous avez plusieurs rôles, le tableau de bord réunit les éléments de chacun.</p><table tabindex="0"><thead><tr><th>Rôle</th><th>À traiter</th><th>Blocs du jour</th></tr></thead><tbody><tr><td>Enseignant</td><td>Évaluations passées dont les notes sont à saisir ; justificatifs d&#39;absence de vos classes</td><td><strong>Mes cours aujourd&#39;hui</strong> : vos cours du jour, le cours en cours mis en évidence, et pour chaque classe <strong>Appel fait</strong> ou le bouton <strong>Faire l&#39;appel</strong></td></tr><tr><td>Vie scolaire</td><td>Classes sans appel aujourd&#39;hui ; justificatifs d&#39;absence à examiner</td><td><strong>Vie scolaire aujourd&#39;hui</strong> (absents, retards, absences non justifiées, incidents des 7 derniers jours) ; <strong>Prochains conseils de discipline</strong></td></tr><tr><td>Secrétariat</td><td>Candidatures en attente ; demandes de transfert de site</td><td><strong>Prochains conseils de discipline</strong></td></tr><tr><td>Caisse</td><td>Vos dépenses en attente de validation</td><td><strong>Caisse aujourd&#39;hui</strong> (total encaissé, derniers paiements) ; <strong>Échéances dépassées</strong></td></tr><tr><td>Internat</td><td>—</td><td><strong>Internat aujourd&#39;hui</strong> : lits occupés, appel du matin et appel du soir</td></tr><tr><td>Infirmerie</td><td>—</td><td><strong>Infirmerie aujourd&#39;hui</strong> : passages du jour et derniers passages</td></tr><tr><td>Administrateur</td><td>Candidatures, transferts de site, justificatifs d&#39;absence, dépenses à valider, demandes de congé, mutations du personnel</td><td><strong>Échéances dépassées</strong>, puis le pilotage : voir <a href="/era-guide/guide/admin/tableau-de-bord.html">Tableau de bord</a></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Quelles classes doivent faire l&#39;appel aujourd&#39;hui ?</p><p>Une classe est attendue les jours où elle a un cours à l&#39;emploi du temps. Si l&#39;établissement n&#39;a pas encore saisi d&#39;emploi du temps, toutes les classes qui ont des élèves sont attendues du lundi au vendredi.</p></div><h3 id="echeances-depassees" tabindex="-1">Échéances dépassées <a class="header-anchor" href="#echeances-depassees" aria-label="Permalink to &quot;Échéances dépassées&quot;">​</a></h3><p>Ce bloc, visible par la caisse et l&#39;administration, liste les familles en retard sur leur échéancier : le montant total en retard, le nombre de familles, puis les cinq retards les plus importants avec la date depuis laquelle chacun court. Cliquez sur une famille pour ouvrir son dossier financier, ou sur <strong>Voir tous les retards</strong> pour la liste complète dans <strong>Facturation</strong>.</p><p>Une échéance est en retard à partir du lendemain de sa date d&#39;échéance, tant que les paiements reçus ne la couvrent pas.</p><h2 id="demander-de-l-aide-sur-la-page-ou-vous-etes" tabindex="-1">Demander de l&#39;aide sur la page où vous êtes <a class="header-anchor" href="#demander-de-l-aide-sur-la-page-ou-vous-etes" aria-label="Permalink to &quot;Demander de l&#39;aide sur la page où vous êtes&quot;">​</a></h2><p>Le bouton <strong>?</strong> en haut à droite ouvre le panneau « Que puis-je faire ici ? ». Il répond pour la page affichée, pas en général : ce à quoi elle sert, et la liste des actions qu&#39;elle permet — seulement celles auxquelles vous avez droit, avec votre rôle. Chaque action renvoie, si vous voulez le détail, vers la page correspondante de ce guide.</p><p>Sur les pages où une erreur coûte cher — préparer une année, saisir des notes, faire l&#39;appel, encaisser un paiement — le panneau propose en plus une <strong>visite guidée</strong> : l&#39;application se met en avant elle-même, encadré par encadré, en surlignant les zones dont elle parle. Vous pouvez l&#39;arrêter à tout moment, et la relancer plus tard — le bouton indique alors « Revoir la visite guidée ».</p><p>Les formulaires de création et de modification n&#39;ont pas de fiche à eux : la page qui y mène l&#39;explique déjà. Le panneau vous y propose simplement le guide.</p><h2 id="retrouver-ce-guide-depuis-l-application" tabindex="-1">Retrouver ce guide depuis l&#39;application <a class="header-anchor" href="#retrouver-ce-guide-depuis-l-application" aria-label="Permalink to &quot;Retrouver ce guide depuis l&#39;application&quot;">​</a></h2><p>Ce guide s&#39;ouvre directement depuis ERA, à deux endroits :</p><ul><li><strong>Votre menu de compte</strong> (votre avatar) → <strong>Guide d&#39;utilisation</strong>.</li><li><strong>Le bloc « Besoin d&#39;aide ? »</strong> en bas de votre tableau de bord, ou de votre espace pour un parent ou un élève.</li></ul><p>Les deux ouvrent la section écrite pour <strong>votre rôle</strong> : un enseignant arrive sur les pages enseignant, un caissier sur les pages caisse. Le lien <strong>Sommaire du guide</strong> mène à la table des matières complète. La langue suit celle de l&#39;application.</p><h2 id="parametres-du-compte" tabindex="-1">Paramètres du compte <a class="header-anchor" href="#parametres-du-compte" aria-label="Permalink to &quot;Paramètres du compte&quot;">​</a></h2><p>Le menu <strong>Paramètres</strong> (accessible depuis votre avatar, en bas de la colonne des espaces, ou en haut à droite sur téléphone) regroupe tout ce qui concerne votre compte personnel, quel que soit votre rôle :</p><ul><li><strong>Profil</strong> — modifier votre nom, votre adresse e-mail et votre photo de profil. Si vous changez d&#39;adresse e-mail, un message « Votre adresse e-mail n&#39;est pas vérifiée » apparaît jusqu&#39;à ce que vous cliquiez sur le lien reçu par e-mail. Un compte parent ou élève peut aussi y être supprimé. Un compte du personnel, lui, est rattaché à des données de l&#39;établissement (emploi du temps, notes, dépenses) : sa suppression se demande à l&#39;administration.</li><li><strong>Sécurité</strong> — changer votre mot de passe, activer l&#39;authentification à deux facteurs, gérer vos clés d&#39;accès (connexion sans mot de passe) et consulter vos sessions actives.</li><li><strong>Apparence</strong> — choisir entre thème clair, sombre ou automatique.</li><li><strong>Langue</strong> — choisir la langue de l&#39;application (français ou anglais). Ce choix change immédiatement tous les libellés, y compris ceux de ce guide si vous y accédez depuis l&#39;app.</li><li><strong>Notifications</strong> — activer les notifications push sur cet appareil.</li></ul><h3 id="authentification-a-deux-facteurs-2fa" tabindex="-1">Authentification à deux facteurs (2FA) <a class="header-anchor" href="#authentification-a-deux-facteurs-2fa" aria-label="Permalink to &quot;Authentification à deux facteurs (2FA)&quot;">​</a></h3><p>Dans <strong>Paramètres → Sécurité → Authentification à deux facteurs</strong>, cliquez sur <strong>Activer la 2FA</strong>. Un code secret vous sera ensuite demandé à chaque connexion ; il se récupère depuis une application d&#39;authentification (TOTP) installée sur votre téléphone, après avoir scanné le code affiché à l&#39;écran. Pour désactiver la 2FA, retournez sur cette même page et cliquez sur <strong>Désactiver la 2FA</strong>.</p><h3 id="sessions-actives" tabindex="-1">Sessions actives <a class="header-anchor" href="#sessions-actives" aria-label="Permalink to &quot;Sessions actives&quot;">​</a></h3><p><strong>Paramètres → Sécurité → Sessions actives</strong> liste tous les appareils actuellement connectés à votre compte, avec l&#39;appareil, l&#39;adresse IP et la dernière activité. L&#39;appareil que vous utilisez en ce moment est marqué <strong>Appareil actuel</strong>. Vous pouvez :</p><ul><li><strong>Déconnecter</strong> un appareil précis (il devra se reconnecter),</li><li><strong>Déconnecter les autres appareils</strong> pour fermer toutes les sessions sauf celle en cours — utile si vous pensez qu&#39;un appareil ne devrait plus avoir accès à votre compte.</li></ul><h3 id="notifications-push" tabindex="-1">Notifications push <a class="header-anchor" href="#notifications-push" aria-label="Permalink to &quot;Notifications push&quot;">​</a></h3><p><strong>Paramètres → Notifications</strong> vous permet d&#39;activer les notifications push sur l&#39;appareil que vous utilisez. Une fois activées, vous êtes notifié dès qu&#39;une action nécessite votre attention (par exemple une demande de transfert inter-site à valider). Le bouton <strong>Activer</strong>/ <strong>Désactiver</strong> bascule cet état ; s&#39;il indique que les notifications ne sont pas prises en charge, c&#39;est que votre navigateur ou votre appareil ne le permet pas.</p><h2 id="la-cloche-de-notifications" tabindex="-1">La cloche de notifications <a class="header-anchor" href="#la-cloche-de-notifications" aria-label="Permalink to &quot;La cloche de notifications&quot;">​</a></h2><p>En haut de l&#39;écran, la cloche affiche un badge quand vous avez des notifications non lues (par exemple une candidature à traiter, ou une demande à valider). Cliquez sur une notification pour l&#39;ouvrir et la marquer comme lue, ou utilisez <strong>Tout marquer comme lu</strong> pour vider la liste d&#39;un coup.</p><h2 id="valider-une-demande-directement-depuis-une-notification" tabindex="-1">Valider une demande directement depuis une notification <a class="header-anchor" href="#valider-une-demande-directement-depuis-une-notification" aria-label="Permalink to &quot;Valider une demande directement depuis une notification&quot;">​</a></h2><p>Certaines notifications ne servent pas seulement à prévenir : elles ouvrent un écran de <strong>validation rapide</strong>, volontairement réduit à l&#39;essentiel, où vous décidez sans naviguer dans le reste de l&#39;app. C&#39;est prévu pour être utilisé depuis un téléphone.</p><p>Trois demandes fonctionnent ainsi :</p><table tabindex="0"><thead><tr><th>Demande</th><th>Qui la valide</th></tr></thead><tbody><tr><td>Transfert d&#39;un élève vers un autre site</td><td>Administration ou secrétariat</td></tr><tr><td>Transfert d&#39;un membre du personnel</td><td>Administration</td></tr><tr><td>Dépense à approuver</td><td>Administration</td></tr></tbody></table><p>L&#39;écran affiche le détail de la demande et deux actions : <strong>Approuver</strong>, qui statue immédiatement, ou <strong>Rejeter</strong>, qui demande d&#39;abord un motif — motif ensuite visible par la personne qui avait déposé la demande.</p><p>Vous pouvez toujours traiter ces demandes de la façon classique, depuis la file correspondante dans le menu. La validation rapide est un raccourci, pas un circuit séparé : une demande déjà traitée depuis une notification apparaît comme traitée dans la file, et inversement.</p><h2 id="pourquoi-certains-menus-n-apparaissent-pas" tabindex="-1">Pourquoi certains menus n&#39;apparaissent pas <a class="header-anchor" href="#pourquoi-certains-menus-n-apparaissent-pas" aria-label="Permalink to &quot;Pourquoi certains menus n&#39;apparaissent pas&quot;">​</a></h2><p>ERA se vend par pôles : un établissement n&#39;active que ceux dont il a besoin. Si un menu attendu n&#39;est pas là, ce n&#39;est pas nécessairement un problème de droits — le pôle concerné n&#39;est peut-être simplement pas inclus dans la licence de l&#39;établissement.</p><p>Deux causes possibles, à distinguer avant de signaler un incident :</p><ul><li><strong>Votre rôle</strong> ne donne pas accès à cette fonction. Un enseignant ne voit pas la caisse, un caissier ne saisit pas de notes.</li><li><strong>Le pôle n&#39;est pas licencié</strong> pour l&#39;établissement. Dans ce cas, personne ne voit la fonction, quel que soit son rôle, et ouvrir l&#39;adresse directement affiche un message indiquant que la fonction n&#39;est pas incluse.</li></ul><p>Votre administrateur peut confirmer lequel des deux cas s&#39;applique.</p><h2 id="changer-de-langue" tabindex="-1">Changer de langue <a class="header-anchor" href="#changer-de-langue" aria-label="Permalink to &quot;Changer de langue&quot;">​</a></h2><p>Le sélecteur de langue (menu <strong>Paramètres → Langue</strong>, ou l&#39;icône de langue dans l&#39;en-tête selon votre rôle) bascule immédiatement toute l&#39;interface entre français et anglais — aucune reconnexion nécessaire.</p><h2 id="conditions-d-utilisation-et-donnees-personnelles" tabindex="-1">Conditions d&#39;utilisation et données personnelles <a class="header-anchor" href="#conditions-d-utilisation-et-donnees-personnelles" aria-label="Permalink to &quot;Conditions d&#39;utilisation et données personnelles&quot;">​</a></h2><p>Deux pages accessibles à tous, y compris sans être connecté, depuis les liens en bas de la page d&#39;accueil :</p><ul><li><strong>CGU / CGV</strong> — les conditions générales d&#39;utilisation et de vente : ce que couvre la licence de votre établissement, la maintenance, et les formules d&#39;hébergement.</li><li><strong>Politique de confidentialité</strong> — quelles données ERA traite sur les élèves, les familles et le personnel, pendant combien de temps elles sont conservées, et qui y a accès.</li></ul><p>Ces deux pages suivent la langue de l&#39;application : elles s&#39;affichent en français ou en anglais selon le réglage de <strong>Paramètres → Langue</strong>.</p>',59)])])}const g=s(r,[["render",i]]);export{m as __pageData,g as default};
